contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 x, uint256 d) public {
        require(d > 0);
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(x); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(d); if (__ESBMC_reverted()) return;
        bool recordedBefore = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(recordedBefore == false && reverted == true && c.hasPlayerWagered(address(this)) == false);
    }
    receive() external payable {}
}

