pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 x, uint256 d) internal {
        vm.assume(d > 0);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(x) {} catch { return; }
        try c.AdjustDifficulty(d) {} catch { return; }
        bool recordedBefore;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { recordedBefore = __r; } catch { return; }
        bool reverted;
        try c.play() { reverted = false; } catch { reverted = true; }
        assertTrue(recordedBefore == false && reverted == true && c.hasPlayerWagered(address(this)) == false);
    }

    function testFuzz_run(uint256 x, uint256 d) public {
        _run(x, d);
    }

    receive() external payable {}
}
